package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CharSequenceTranslator_with_TriageGen1Test {

    /**
     * Mock implementation of CharSequenceTranslator to test the aggregation logic.
     */
    private static class MockTranslator extends CharSequenceTranslator {
        private final String replacement;

        MockTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }
    }

    @Test
    public void testWith_SingleTranslator() throws IOException {
        CharSequenceTranslator base = new MockTranslator("base");
        CharSequenceTranslator extra = new MockTranslator("extra");

        CharSequenceTranslator result = base.with(extra);

        assertNotNull(result);
        assertTrue(result instanceof AggregateTranslator);

        StringWriter sw = new StringWriter();
        // The aggregate translator should apply translators in order: base, then extra
        // However, the implementation of AggregateTranslator's translate method 
        // typically iterates through the array and applies them.
        // Based on the 'with' implementation, 'this' is at index 0.
        result.translate("test", sw);

        // In Apache Commons Lang3, AggregateTranslator applies all translators in the array.
        // Since 'base' is at [0] and 'extra' is at [1], both should execute.
        assertEquals("baseextra", sw.toString());
    }

    @Test
    public void testWith_MultipleTranslators() throws IOException {
        CharSequenceTranslator base = new MockTranslator("A");
        CharSequenceTranslator t1 = new MockTranslator("B");
        CharSequenceTranslator t2 = new MockTranslator("C");

        CharSequenceTranslator result = base.with(t1, t2);

        StringWriter sw = new StringWriter();
        result.translate("test", sw);

        assertEquals("ABC", sw.toString());
    }

    @Test
    public void testWith_EmptyArray() throws IOException {
        CharSequenceTranslator base = new MockTranslator("base");

        // Passing an empty varargs array
        CharSequenceTranslator result = base.with();

        StringWriter sw = new StringWriter();
        result.translate("test", sw);

        // Should only contain the base translator
        assertEquals("base", sw.toString());
    }

    @Test
    public void testWith_NullArgument() {
        // Note: Passing null to a varargs parameter results in the array itself being null.
        // This will trigger a NullPointerException in the method due to translators.length.
        CharSequenceTranslator base = new MockTranslator("base");

        try {
            base.with(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Success
        }
    }
}
